"""Typed request and result contracts for the clarification child state."""

from enum import StrEnum

from pydantic import BaseModel, ConfigDict, Field


class ClarificationRequestDTO(BaseModel):
    """One material uncertainty delegated by an invoking AI state."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    clarification_ref: str = Field(
        min_length=1,
        description=(
            "Descriptive run-scoped identifier generated by the invoking LLM for this "
            "logical doubt; reuse it if the same doubt is retried."
        ),
    )
    goal: str = Field(
        min_length=1,
        description="Functional goal the invoking state is trying to complete.",
    )
    uncertainty: str = Field(
        min_length=1,
        description="Specific missing or ambiguous point that may need a user answer.",
    )
    relevant_context: str = Field(
        min_length=1,
        description="Bounded factual context available for understanding the uncertainty.",
    )
    relevant_refs: list[str] = Field(
        default_factory=list,
        description="Active model-facing references relevant to the doubt, never backend IDs.",
    )


class ClarificationOutcome(StrEnum):
    """Functional interpretation returned to the invoking state."""

    RESOLVED = "resolved"
    UNRESOLVED = "unresolved"
    DECLINED = "declined"
    TIMED_OUT = "timed_out"
    NOT_NEEDED = "not_needed"


class ClarificationResultDTO(BaseModel):
    """Compact interpreted clarification returned through the parent tool call."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    clarification_ref: str = Field(
        min_length=1,
        description="The exact logical doubt reference received from the invoking state.",
    )
    outcome: ClarificationOutcome = Field(
        description="How the available context and user interaction resolved the doubt."
    )
    user_answer: str | None = Field(
        default=None,
        description="Concise normalized user answer when one was received.",
    )
    resolved_point: str | None = Field(
        default=None,
        description="Functional fact the invoking state can apply to its original work.",
    )
    remaining_uncertainty: str | None = Field(
        default=None,
        description="What remains unclear when the doubt was not fully resolved.",
    )

